INSERT OR IGNORE INTO products (id,slug,sku,name,category,subcategory,collection,description,composition,care,fit,price,old_price,images,is_new,rank,status) VALUES ('p021','transit-crossbody','LL-021','Сумка Transit Crossbody','accessories','bags','Everyday Objects','Компактная сумка для телефона, ключей и небольших вещей. Регулируемый ремень, внутренний карман и наружная молния помогают держать всё под рукой.','100% полиамид; подкладка: 100% полиэстер','Очищать влажной тканью с мягким мылом. Не использовать отбеливатель. Сушить естественным способом вдали от прямого солнца.','24 × 16 × 7 см; ремень 70–130 см.',590000,NULL,'["/images/transit-crossbody.svg","/images/transit-crossbody-study.svg","/images/transit-crossbody-graphite.svg"]',0,20,'published');
