INSERT OR IGNORE INTO products (id,slug,sku,name,category,subcategory,collection,description,composition,care,fit,price,old_price,images,is_new,rank,status) VALUES ('p022','archive-tote','LL-022','Сумка Archive Tote','accessories','bags','Urban Archive','Плотный шоппер с широким дном и внутренним карманом. Короткие и длинные ручки позволяют менять способ носки, а лаконичная графика не спорит с одеждой.','100% хлопок, канвас 400 г/м²','Очищать влажной тканью с мягким мылом. Не использовать отбеливатель. Сушить естественным способом вдали от прямого солнца.','38 × 40 × 12 см; ручки 25 и 62 см.',490000,590000,'["/images/archive-tote.svg","/images/archive-tote-study.svg","/images/archive-tote-graphite.svg"]',0,21,'published');
