INSERT OR IGNORE INTO products (id,slug,sku,name,category,subcategory,collection,description,composition,care,fit,price,old_price,images,is_new,rank,status) VALUES ('p023','daypack-02','LL-023','Рюкзак Daypack 02','accessories','bags','Future Heritage','Городской рюкзак с отдельным мягким отделением и двумя боковыми карманами. Матовая фактура, округлая верхняя часть и аккуратная фурнитура.','100% полиамид; подкладка: 100% полиэстер','Очищать влажной тканью с мягким мылом. Не использовать отбеливатель. Сушить естественным способом вдали от прямого солнца.','42 × 29 × 14 см; объём около 17 л.',1090000,NULL,'["/images/daypack-02.svg","/images/daypack-02-study.svg","/images/daypack-02-graphite.svg"]',1,22,'published');
