INSERT OR IGNORE INTO products (id,slug,sku,name,category,subcategory,collection,description,composition,care,fit,price,old_price,images,is_new,rank,status) VALUES ('p024','weekend-duffle','LL-024','Сумка Weekend Duffle','accessories','bags','Everyday Objects','Мягкая дорожная сумка для коротких поездок. Широкая молния открывает доступ к основному отделению, съёмный ремень освобождает руки.','100% полиэстер; подкладка: 100% полиэстер','Очищать влажной тканью с мягким мылом. Не использовать отбеливатель. Сушить естественным способом вдали от прямого солнца.','48 × 27 × 24 см; объём около 30 л.',990000,NULL,'["/images/weekend-duffle.svg","/images/weekend-duffle-study.svg","/images/weekend-duffle-graphite.svg"]',0,23,'published');
