INSERT OR IGNORE INTO products (id,slug,sku,name,category,subcategory,collection,description,composition,care,fit,price,old_price,images,is_new,rank,status) VALUES ('p025','core-cap','LL-025','Кепка Core Cap','accessories','headwear','Core Collection','Шестипанельная кепка из плотного хлопка с вышитым знаком LL. Изогнутый козырёк и металлический регулятор дополняют узнаваемую базовую форму.','100% хлопок','Деликатная стирка при 30 °C наизнанку с вещами похожих цветов. Не отбеливать и не сушить в машине. Гладить с изнанки на низкой температуре.','Обхват 54–60 см, регулируемая застёжка.',350000,NULL,'["/images/core-cap.svg","/images/core-cap-study.svg","/images/core-cap-graphite.svg"]',0,24,'published');
