INSERT OR IGNORE INTO products (id,slug,sku,name,category,subcategory,collection,description,composition,care,fit,price,old_price,images,is_new,rank,status) VALUES ('p026','rib-beanie','LL-026','Шапка Rib Beanie','accessories','headwear','Everyday Objects','Шапка в крупный рубчик с широким отворотом. Мягкая пряжа и эластичная вязка дают комфортную посадку без избыточного объёма.','50% шерсть, 50% акрил','Ручная стирка при температуре до 30 °C со средством для шерсти. Сушить горизонтально. Не выкручивать.','Обхват 54–60 см, эластичная вязка.',290000,NULL,'["/images/rib-beanie.svg","/images/rib-beanie-study.svg","/images/rib-beanie-graphite.svg"]',0,25,'published');
