INSERT OR IGNORE INTO products (id,slug,sku,name,category,subcategory,collection,description,composition,care,fit,price,old_price,images,is_new,rank,status) VALUES ('p027','bucket-archive','LL-027','Панама Archive Bucket','accessories','headwear','Urban Archive','Панама из плотного твила с прошитым полем и компактным текстильным ярлыком. Спокойная форма завершает образ с курткой или лёгкой рубашкой.','100% хлопок, твил','Деликатная стирка при 30 °C наизнанку с вещами похожих цветов. Не отбеливать и не сушить в машине. Гладить с изнанки на низкой температуре.','Размеры S/M: 56–58 см; L/XL: 59–61 см.',390000,490000,'["/images/bucket-archive.svg","/images/bucket-archive-study.svg","/images/bucket-archive-graphite.svg"]',0,26,'published');
