INSERT OR IGNORE INTO products (id,slug,sku,name,category,subcategory,collection,description,composition,care,fit,price,old_price,images,is_new,rank,status) VALUES ('p028','five-panel-cap','LL-028','Кепка Five Panel','accessories','headwear','Future Heritage','Пятипанельная кепка с плоским козырьком и регулируемой стропой. Лёгкий материал и минимальные детали продолжают технический язык коллекции.','100% полиамид','Деликатная стирка при 30 °C наизнанку с вещами похожих цветов. Не отбеливать и не сушить в машине. Гладить с изнанки на низкой температуре.','Обхват 54–60 см, регулируемая стропа.',420000,NULL,'["/images/five-panel-cap.svg","/images/five-panel-cap-study.svg","/images/five-panel-cap-graphite.svg"]',1,27,'published');
