INSERT OR IGNORE INTO products (id,slug,sku,name,category,subcategory,collection,description,composition,care,fit,price,old_price,images,is_new,rank,status) VALUES ('p029','daily-socks','LL-029','Носки Daily Set','accessories','objects','Everyday Objects','Комплект из двух пар высоких носков с плотной резинкой и небольшим знаком LegacyLab. Спокойная графика хорошо читается с короткими брюками и кедами.','80% хлопок, 17% полиамид, 3% эластан','Деликатная стирка при 30 °C наизнанку с вещами похожих цветов. Не отбеливать и не сушить в машине. Гладить с изнанки на низкой температуре.','Высокий силуэт; размеры 36–40 и 41–45.',190000,NULL,'["/images/daily-socks.svg","/images/daily-socks-study.svg","/images/daily-socks-graphite.svg"]',0,28,'published');
