INSERT OR IGNORE INTO products (id,slug,sku,name,category,subcategory,collection,description,composition,care,fit,price,old_price,images,is_new,rank,status) VALUES ('p030','utility-belt','LL-030','Ремень Utility Belt','accessories','objects','Urban Archive','Текстильный ремень с матовой металлической пряжкой и аккуратно обработанным концом. Длину легко настроить под разные способы носки.','Стропа: 100% полиэстер; пряжка: алюминиевый сплав','Очищать влажной тканью с мягким мылом. Не использовать отбеливатель. Сушить естественным способом вдали от прямого солнца.','Длина 120 см, ширина 3,5 см.',290000,NULL,'["/images/utility-belt.svg","/images/utility-belt-study.svg","/images/utility-belt-graphite.svg"]',0,29,'published');
