INSERT OR IGNORE INTO products (id,slug,sku,name,category,subcategory,collection,description,composition,care,fit,price,old_price,images,is_new,rank,status) VALUES ('p031','archive-scarf','LL-031','Шарф Archive Scarf','accessories','objects','Core Collection','Длинный шарф с мягкой бахромой и тональным знаком на краю. Объёмное плетение создаёт живую фактуру в монохромном образе.','50% шерсть, 50% акрил','Ручная стирка при температуре до 30 °C со средством для шерсти. Сушить горизонтально. Не выкручивать.','180 × 30 см, без учёта бахромы.',590000,NULL,'["/images/archive-scarf.svg","/images/archive-scarf-study.svg","/images/archive-scarf-graphite.svg"]',0,30,'published');
