INSERT OR IGNORE INTO products (id,slug,sku,name,category,subcategory,collection,description,composition,care,fit,price,old_price,images,is_new,rank,status) VALUES ('p032','key-loop','LL-032','Брелок Key Loop','accessories','objects','Future Heritage','Короткая петля из плотной стропы с карабином и кольцом. Небольшой цветовой акцент, который можно закрепить на сумке или шлёвке брюк.','Стропа: 100% полиэстер; фурнитура: цинковый сплав','Очищать влажной тканью с мягким мылом. Не использовать отбеливатель. Сушить естественным способом вдали от прямого солнца.','Длина 15 см, ширина 2,5 см.',220000,NULL,'["/images/key-loop.svg","/images/key-loop-study.svg","/images/key-loop-graphite.svg"]',1,31,'published');
